using System;using System.Collections;using System.Collections.Generic;using System.Diagnostics;using System.IO;using System.Linq;using System.Reflection;using System.Xml;
namespace OwnLabView {
public static class Libraries {
 internal static Dictionary<string,object> Validate(string path){path=Path.GetFullPath(path);if(!path.StartsWith(Path.Combine(Storage.Root,"projects")+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase)||Path.GetExtension(path)!=".lvlib")throw new ArgumentException("Own library path required.");Storage.NoReparse(path);string report=Path.Combine(Path.GetDirectoryName(path),"library-report.json");var doc=Data.Map(Data.Json.DeserializeObject(File.ReadAllText(report)));if(!Object.Equals(doc["created"],true)||Data.Text(doc,"library_path")!=path||Data.Text(doc,"library_sha256")!=Data.Hash(path))throw new IOException("Library differs from its successful report.");foreach(var raw in Data.Array(doc["files"])){var row=Data.Map(raw);string file=Data.Text(row,"path");Storage.NoReparse(file);if(!file.StartsWith(Path.GetDirectoryName(path)+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase)||Data.Hash(file)!=Data.Text(row,"sha256"))throw new IOException("Library snapshot file differs: "+file);}return doc;}
 static string[] Parse(Dictionary<string,object> args){Data.Keys(args,"name","member_paths","source_library","remove_members");Storage.ArtifactFilename(Data.Text(args,"name")+".lvlib",".lvlib");var members=args.ContainsKey("member_paths")?Data.Array(args["member_paths"]).Select(x=>{if(!(x is string))throw new ArgumentException("Member path must be string.");return (string)x;}).ToArray():new string[0];if(members.Length>64||members.Distinct(StringComparer.OrdinalIgnoreCase).Count()!=members.Length)throw new ArgumentException("At most64 distinct library members.");foreach(string member in members)Projects.ValidateMember(member);if(args.ContainsKey("source_library"))Validate(Data.Text(args,"source_library"));else if(args.ContainsKey("remove_members"))throw new ArgumentException("remove_members requires source_library.");if(args.ContainsKey("remove_members"))foreach(object value in Data.Array(args["remove_members"]))if(!(value is string)||String.IsNullOrWhiteSpace((string)value))throw new ArgumentException("remove_members requires exact native member names.");return members;}
 public static object Create(Dictionary<string,object> args){Parse(args);NiApplicationLifetime.EnsureForBuild();string folder=Path.Combine(Storage.Root,"projects","L_"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(folder);string request=Path.Combine(folder,"library-request.json");Storage.WriteNew(request,args);var start=new ProcessStartInfo(Path.Combine(Storage.Root,"bin","OwnLabViewMcp.exe"),"--library-worker \""+request+"\""){UseShellExecute=false,CreateNoWindow=true,WindowStyle=ProcessWindowStyle.Hidden,RedirectStandardOutput=true,RedirectStandardError=true,WorkingDirectory=Storage.Root};using(var child=Process.Start(start)){var output=child.StandardOutput.ReadToEndAsync();var errors=child.StandardError.ReadToEndAsync();if(!child.WaitForExit(180000)){child.Kill();throw new TimeoutException("Library worker timed out; retained "+folder);}if(child.ExitCode!=0)throw new IOException("Library creation failed: "+errors.Result+" Retained "+folder);}return Data.Json.DeserializeObject(File.ReadAllText(Path.Combine(folder,"library-report.json")));}
 static string CopyLibrary(string source,string directory,Dictionary<string,string> originals){var report=Validate(source);Directory.CreateDirectory(directory);string root=Path.GetDirectoryName(source);foreach(var raw in Data.Array(report["files"])){var row=Data.Map(raw);string path=Data.Text(row,"path"),target=Path.Combine(directory,path.Substring(root.Length+1));Directory.CreateDirectory(Path.GetDirectoryName(target));File.Copy(path,target,false);originals[path]=Data.Text(row,"sha256");}return Path.Combine(directory,Path.GetFileName(source));}
 public static object Worker(string request){request=Path.GetFullPath(request);Storage.NoReparse(request);if(!request.StartsWith(Path.Combine(Storage.Root,"projects")+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase)||Path.GetFileName(request)!="library-request.json")throw new ArgumentException("Isolated library request required.");var args=Data.Map(Data.Json.DeserializeObject(File.ReadAllText(request)));string[] inputs=Parse(args);string folder=Path.GetDirectoryName(request),target=Path.Combine(folder,Data.Text(args,"name")+".lvlib");var originals=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);object connection=null,project=null,app=null;var refs=new List<object>();string phase="copy";try{
 if(args.ContainsKey("source_library")){target=CopyLibrary(Data.Text(args,"source_library"),folder,originals);if(args.ContainsKey("remove_members")){var xml=ProjectLayout.Read(target);foreach(string name in Data.Array(args["remove_members"]).Cast<string>()){var matches=xml.DocumentElement.SelectNodes("Item").Cast<XmlElement>().Where(x=>x.GetAttribute("Name")==name).ToArray();if(matches.Length!=1)throw new ArgumentException("Removal name must identify one direct library member: "+name);xml.DocumentElement.RemoveChild(matches[0]);}xml.Save(target);}}
 using(var lease=new NiSessionLease()){connection=Activator.CreateInstance(Type.GetTypeFromProgID("LabVIEW.Application",true));lease.Attached();project=LabView.Invoke(connection,"NewProject",BindingFlags.InvokeMethod);app=LabView.Invoke(project,"Application",BindingFlags.GetProperty);var seen=new HashSet<string>(StringComparer.OrdinalIgnoreCase);var hashes=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);
 if(!File.Exists(target)){phase="create_library";object helper=ClassArtifacts.OpenAuxiliary(app,refs,"OwnLibrary20261013_Create.vi",seen,hashes);LabView.Invoke(helper,"SetControlValue",BindingFlags.InvokeMethod,"Save Library Path",target);LabView.Invoke(helper,"Run",BindingFlags.InvokeMethod,false);ClassArtifacts.CheckError(helper);}var stagedLibraries=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);foreach(string source in inputs.Where(p=>Path.GetExtension(p).Equals(".lvlib",StringComparison.OrdinalIgnoreCase))){string copied=CopyLibrary(source,Path.Combine(folder,"nested_"+Guid.NewGuid().ToString("N").Substring(0,8)),originals);var xml=ProjectLayout.Read(target);var node=xml.CreateElement("Item");node.SetAttribute("Name",Path.GetFileName(copied));node.SetAttribute("Type","Library");node.SetAttribute("URL",new Uri(target+Path.DirectorySeparatorChar).MakeRelativeUri(new Uri(copied)).ToString());xml.DocumentElement.AppendChild(node);xml.Save(target);stagedLibraries[source]=copied;}phase="open_staged_library";object library=LabView.Invoke(app,"OpenLibrary",BindingFlags.InvokeMethod,target);refs.Add(library);var additions=new List<object>();using(var n=new TypeImport.Session(app,refs)){
 foreach(string source in inputs){phase="copy_member";originals[source]=Data.Hash(source);string ext=Path.GetExtension(source).ToLowerInvariant(),directory=Path.Combine(folder,"m"+Guid.NewGuid().ToString("N").Substring(0,8)),copy;Directory.CreateDirectory(directory);
 if(ext==".lvlib")copy=stagedLibraries[source];
 else if(ext==".lvclass"){var bundle=ClassSnapshot.Copy(source,directory,"class-snapshot");copy=bundle.Target;foreach(var pair in bundle.Sources)originals[pair.Key]=pair.Value;}
 else {object original=n.Open(source);int type=n.Type(original);var closure=n.Audit(TypeImport.Session.Paths(original));if(type==1){var copied=MethodBody.Copy(app,refs,n,source,directory,closure,seen,hashes);copy=copied.Path;foreach(var raw in copied.Files){var row=Data.Map(Data.Json.DeserializeObject(Data.Json.Serialize(raw)));originals[Data.Text(row,"source_path")]=Data.Text(row,"source_sha256");}}else {if(closure.Select(x=>Data.Map(Data.Json.DeserializeObject(Data.Json.Serialize(x)))).Any(r=>!NiDistribution.AcceptDependency(Data.Text(r,"path"))))throw new ArgumentException("Typed/global library members with own external dependencies require a self-contained snapshot.");copy=Path.Combine(directory,Path.GetFileNameWithoutExtension(source)+"_"+Guid.NewGuid().ToString("N").Substring(0,8)+ext);File.Copy(source,copy,false);}}
 phase="add_native_member";object item=null;if(ext==".lvlib"){foreach(object candidate in (IEnumerable)LabView.Invoke(library,"Children",BindingFlags.GetProperty)){refs.Add(candidate);if(TypeImport.NativePath(Convert.ToString(LabView.Invoke(candidate,"Path",BindingFlags.GetProperty))).Equals(copy,StringComparison.OrdinalIgnoreCase))item=candidate;}if(item==null)throw new IOException("Staged nested library member missing.");}else {item=LabView.Invoke(library,"AddFile",BindingFlags.InvokeMethod,copy);refs.Add(item);}phase="save_native_member";if(ext==".lvclass"||ext==".lvlib"){object nested=LabView.Invoke(app,"OpenLibrary",BindingFlags.InvokeMethod,copy);refs.Add(nested);LabView.Invoke(nested,"Save",BindingFlags.InvokeMethod,copy);}else {object vi=n.Open(copy);LabView.Invoke(vi,"SaveInstrument",BindingFlags.InvokeMethod,copy,false,false);if(n.Type(vi)==1&&Convert.ToInt32(LabView.Invoke(vi,"ExecState",BindingFlags.GetProperty))!=1)throw new IOException("Library member is not executable.");}LabView.Invoke(library,"Save",BindingFlags.InvokeMethod,target);additions.Add(new{source_path=source,path=copy,name=Convert.ToString(LabView.Invoke(item,"Name",BindingFlags.GetProperty)),type=Convert.ToString(LabView.Invoke(item,"TypeString",BindingFlags.GetProperty))});}
 }
 phase="native_verify";var native=new List<object>();Visit(app,library,refs,folder,native,0);LabView.Invoke(library,"Save",BindingFlags.InvokeMethod,target);foreach(var pair in originals)if(Data.Hash(pair.Key)!=pair.Value)throw new IOException("Library source changed: "+pair.Key);var files=Directory.GetFiles(folder,"*",SearchOption.AllDirectories).Where(p=>new[]{".vi",".ctl",".lvclass",".lvlib",".vim"}.Contains(Path.GetExtension(p),StringComparer.OrdinalIgnoreCase)).Select(p=>new{path=p,sha256=Data.Hash(p)}).ToArray();var report=new{created=true,library_path=target,library_sha256=Data.Hash(target),files,native_members=native,added_members=additions,source_files=originals,source_files_unchanged=true,generated_vis_executed=false,window_operations_used=false};Storage.WriteNew(Path.Combine(folder,"library-report.json"),report);return report;}
 }catch(Exception ex){Storage.WriteNew(Path.Combine(folder,"library-failure.json"),new{phase,error=ex.ToString()});throw;}finally{for(int i=refs.Count-1;i>=0;i--)LabView.Release(refs[i]);LabView.Release(app);if(project!=null)try{LabView.Invoke(project,"Close",BindingFlags.InvokeMethod);}catch{}LabView.Release(project);LabView.Release(connection);}}
 static void Visit(object app,object parent,List<object> refs,string root,List<object> rows,int depth){if(depth>16||rows.Count>256)throw new IOException("Library traversal budget exceeded.");foreach(object item in (IEnumerable)LabView.Invoke(parent,"Children",BindingFlags.GetProperty)){refs.Add(item);string kind=Convert.ToString(LabView.Invoke(item,"TypeString",BindingFlags.GetProperty)),name=Convert.ToString(LabView.Invoke(item,"Name",BindingFlags.GetProperty));if(kind.IndexOf("Folder",StringComparison.OrdinalIgnoreCase)>=0){Visit(app,item,refs,root,rows,depth+1);continue;}string path=TypeImport.NativePath(Convert.ToString(LabView.Invoke(item,"Path",BindingFlags.GetProperty)));if(!path.StartsWith(root+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase))throw new IOException("Library native member escaped snapshot.");if(kind=="Library"||kind=="LVClass"){object lib=LabView.Invoke(app,"OpenLibrary",BindingFlags.InvokeMethod,path);refs.Add(lib);Visit(app,lib,refs,root,rows,depth+1);LabView.Invoke(lib,"Save",BindingFlags.InvokeMethod,path);rows.Add(new{path,name,kind});continue;}object vi=kind=="Class Private Data"?LabView.Invoke(item,"VI",BindingFlags.GetProperty):LabView.Invoke(app,"GetVIReference",BindingFlags.InvokeMethod,path,"",false,0);refs.Add(vi);string actual=TypeImport.NativePath(Convert.ToString(LabView.Invoke(vi,"Path",BindingFlags.GetProperty)));if(!actual.Equals(path,StringComparison.OrdinalIgnoreCase))throw new IOException("Library VI resolved outside copy.");foreach(string dependency in TypeImport.Session.Paths(vi))if(!NiDistribution.AcceptDependency(dependency)&&!dependency.StartsWith(root+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase))throw new IOException("Library dependency outside copied closure: "+dependency);int type=Convert.ToInt32(LabView.Invoke(vi,"VIType",BindingFlags.GetProperty)),state=Convert.ToInt32(LabView.Invoke(vi,"ExecState",BindingFlags.GetProperty));if(type==1&&state!=1)throw new IOException("Library member not compiled: "+path);if(kind!="Class Private Data")LabView.Invoke(vi,"SaveInstrument",BindingFlags.InvokeMethod,path,false,false);rows.Add(new{path,name,kind,vi_type=type,execution_state=state,native_callees=TypeImport.Session.Paths(vi),qualified_name=Convert.ToString(LabView.Invoke(vi,"Name",BindingFlags.GetProperty))});}}
}
}

